3	/// The inspector's **History** section body (issue #59): a newest-first commit log for the selected
4	/// workroom, read via `VCSProviding` through the store-owned `HistoryModel`. Lives inside the
5	/// inspector's scroll view, so it renders a flat `VStack` of rows (like `ChangesPanel`/`FilesPanel`)
6	/// rather than a `List`. Single-click a row opens the commit's `ChangesetDetailView` as a preview
7	/// content tab; a quick double-click persists it (the same gate the Changes panel uses).
8	struct HistoryPanel: View {
9	  @EnvironmentObject var store: AppStore
10	  /// Injected + `@ObservedObject` (mirrors `FilesPanel`), NOT read via `store.commitHistory`: the
11	  /// panel must subscribe to the model's own `@Published` state so its `.loading → .loaded` flip
12	  /// re-renders the pane. `AppStore` doesn't forward `commitHistory`'s `objectWillChange`, so a plain
13	  /// `store.commitHistory` read only refreshed when some *unrelated* store change happened to publish
14	  /// (a status refresh, a reselection, an app refocus) — leaving the loader stuck until then.
15	  @ObservedObject var model: HistoryModel
16	  private let theme = ThemeService.shared
17	
18	  var body: some View {
19	    Group {
20	      if store.inspectorTargetID == nil {
21	        // No active workspace (nothing selected, or the selected workroom has no open tabs) — empty
22	        // out to match the detail pane's "No terminal" state rather than show a stale last workroom.
23	        placeholder("No open terminal", systemImage: "clock")
24	      } else {
25	        switch model.state {
26	        case .idle:
27	          // A workroom is selected (the outer guard handled the nil case), so `.idle` is only the
28	          // brief pre-focus state before the model loads — show the loader, never "Select a
29	          // workroom" (which would wrongly imply no selection).
30	          loadingIndicator
31	        case .loading where model.commits.isEmpty:
32	          loadingIndicator
33	        case .failed(let message):
34	          placeholder(message, systemImage: "exclamationmark.triangle")
35	        default:
36	          if model.commits.isEmpty {
37	            placeholder("No history", systemImage: "clock")
38	          } else {
39	            list
40	          }
41	        }
42	      }
43	    }
44	    // Fill the pane (hosted in fill mode) so the inner `ScrollView` has bounded height and scrolls
45	    // itself — SwiftUI owns the scrolling, which is what lets the divergence accordion animate
46	    // smoothly (see `list`).
47	    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
48	    // No container-level `accessibilityIdentifier` here: SwiftUI propagates a container id onto the
49	    // combined `HistoryRow` leaves, clobbering their own id. The rows carry "HistoryRow"; that the
50	    // pane is showing is asserted via `inspector.header.History` (the canonical section marker).
51	    // Point the model at the inspector's active target (nil once all its tabs close → History
