/// A moved file's row reads `old → new`. The rename is ONE row (both backends pair the delete with
/// the add), so this dimmed path line is the only place the old path appears — if it regressed to
/// the bare path, the row would look like a plain add at a path the user never created.
///
/// Matched on the row's spoken content rather than its `Text`: `ChangesetFileRow` combines its
/// children, so the name + path line surface as the row element's own label/value.
func testRenamedFileRowShowsWhereItMovedFrom() throws {
  let app = launchedApp()
  XCTAssertTrue(app.wait(for: .runningForeground, timeout: 10))
  openHistory(app)

  els(app, "HistoryRow").element(boundBy: 0).click()
  XCTAssertTrue(waitExists(el(app, "ChangesetDetail")), "the changeset detail opens as a tab")
  XCTAssertTrue(
    els(app, "ChangesetFileRow").element(boundBy: 0).waitForExistence(timeout: 8),
    "the changed-file list renders")

  // The fixture's renamed entry: src/moved.rb → lib/moved.rb.
  let moved = app.descendants(matching: .any).matching(
    NSPredicate(
      format: "label CONTAINS %@ OR value CONTAINS %@", "src/moved.rb \u{2192} lib/moved.rb",
      "src/moved.rb \u{2192} lib/moved.rb")
  ).firstMatch
  XCTAssertTrue(waitExists(moved), "the renamed row shows `old → new`, not just the new path")
}

/// jj's virtual root commit gets its own row: `◆ root() 00000000`, with nothing it doesn't have (no
/// author, no relative time) and nothing to click. Before it existed, the oldest row of every jj
/// history read "(no description) · 56 yr ago" behind a `?` avatar — root's blank signature and epoch
/// timestamp rendered as if someone had authored it in 1970.
///
/// Two halves: the row states what it is, and it is INERT (root has no diff, so a click must not open
/// a changeset tab). Its own identifier, not `HistoryRow` — the commit rows are indexed positionally
/// and counted against the unpushed badges elsewhere in this suite.
func testRootRowRendersAsRootAndOpensNothing() throws {
  let app = launchedApp()
  XCTAssertTrue(app.wait(for: .runningForeground, timeout: 10))

  ///
  /// Matching on `value` and not `label` is what keeps this honest: the History row's badge carries
  /// "Not pushed" as its accessibility LABEL, so a label match would find the row and pass regardless of
  /// what the header shows.
  private func headerSaysNotPushed(_ app: XCUIApplication) -> XCUIElement {
    app.descendants(matching: .any).matching(
      NSPredicate(format: "value CONTAINS %@", "Not pushed")
    ).firstMatch
  }

  /// Opening the badged commit states the same fact in the detail header — a badge that vanishes when
  /// you click the row would read as a bug.
  func testChangesetHeaderShowsTheUnpushedMarker() throws {
    let app = launchedApp()
    XCTAssertTrue(app.wait(for: .runningForeground, timeout: 10))
    openHistory(app)

    // Fixture commit 2 is the badged one; open it (row order is newest-first, so index 1).
    els(app, "HistoryRow").element(boundBy: 1).click()
    XCTAssertTrue(waitExists(el(app, "ChangesetDetail")), "the changeset detail opens")
    XCTAssertTrue(
      waitExists(headerSaysNotPushed(app)), "the detail header states the commit isn't pushed")
  }

  /// And the pushed commit's detail says nothing: the marker is a claim about this commit, not a
  /// permanent header fixture.
  func testChangesetHeaderOmitsTheMarkerForAPushedCommit() throws {
    let app = launchedApp()
    XCTAssertTrue(app.wait(for: .runningForeground, timeout: 10))
    openHistory(app)

    // Fixture commit 3 is `.pushed`.
    els(app, "HistoryRow").element(boundBy: 2).click()
    XCTAssertTrue(waitExists(el(app, "ChangesetDetail")), "the changeset detail opens")
    XCTAssertFalse(
      headerSaysNotPushed(app).exists, "a pushed commit's header carries no unpushed marker")
  }
}

